// runs in a Worker: no DOM, no network. It only describes kit components and calls wisp as itself.
const show = (rows, error) => wisp.render({ c: 'Stack', p: { gap: '2' }, k: [
  { c: 'Inline', p: { justify: 'between' }, k: [
    { c: 'Text', p: { weight: 'semibold' }, k: [`${rows.length} plugins`] },
    { c: 'Button', p: { label: 'Refresh', size: 'sm', variant: 'ghost' }, on: 'refresh' },
  ] },
  ...(error ? [{ c: 'Callout', p: { tone: 'bad', title: error } }] : []),
  ...rows.map((r) => ({ c: 'ListRow', p: { title: r.id, sub: `${r.version} · ${r.enabled ? 'on' : 'off'}` } })),
] });
const load = () => wisp.call('plugins.list', {}).then((rows) => show(rows), (e) => show([], e.message));
wisp.on('refresh', load);
show([]);
load();

let note = '';
let loud = false;
const draw = () => wisp.render({ c: 'Stack', p: { gap: '3' }, k: [
  { c: 'SettingsRow', p: { title: 'Loud', description: 'Shows the note as a callout', control: { c: 'Switch', p: { checked: loud }, on: 'loud' } } },
  { c: 'Input', p: { value: note, placeholder: 'A note', label: 'Note' }, on: 'note' },
  loud ? { c: 'Callout', p: { tone: 'info', title: note || 'Nothing yet' } } : { c: 'Text', p: { tone: 'muted', size: 'sm' }, k: [note || 'Nothing yet'] },
] });
wisp.on('note', (v) => { note = String(v); draw(); });
wisp.on('loud', (v) => { loud = v === true; draw(); });
draw();
